CREATE TABLE `combos` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`name` VARCHAR(120) NOT NULL,`description` VARCHAR(1000) NULL,`image_path` VARCHAR(512) NULL,`image_alt` VARCHAR(160) NULL,`price_cents` BIGINT UNSIGNED NOT NULL DEFAULT 0,`sort_order` SMALLINT UNSIGNED NOT NULL DEFAULT 0,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `combos_public_id_key` (`public_id`),UNIQUE INDEX `combos_tenant_id_name_key` (`tenant_id`,`name`),INDEX `combos_tenant_id_active_sort_order_idx` (`tenant_id`,`active`,`sort_order`),CONSTRAINT `combos_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `combo_items` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`combo_id` BIGINT UNSIGNED NOT NULL,`service_id` BIGINT UNSIGNED NOT NULL,`sort_order` SMALLINT UNSIGNED NOT NULL DEFAULT 0,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `combo_items_public_id_key` (`public_id`),UNIQUE INDEX `combo_items_combo_id_service_id_key` (`combo_id`,`service_id`),INDEX `combo_items_tenant_id_combo_id_sort_order_idx` (`tenant_id`,`combo_id`,`sort_order`),INDEX `combo_items_tenant_id_service_id_idx` (`tenant_id`,`service_id`),CONSTRAINT `combo_items_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `combo_items_combo_id_fkey` FOREIGN KEY (`combo_id`) REFERENCES `combos`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `combo_items_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
